"use client";

import { memo, useCallback, useMemo, useState } from "react";
import type { MediaCarouselHandle, MediaCarouselProps } from "./types";
import { useMediaRecovery } from "./hooks/use-media-recovery";
import {
  DEFAULT_MAX_RATIO,
  DEFAULT_MIN_RATIO,
  DEFAULT_PEEK_RATIO,
  clampRatio,
  declaredRatio,
  frameFor,
  resolvePeekRatio,
} from "./lib/aspect";
import { resolveLabels, resolveLocale } from "./lib/labels";
import { CarouselTrack } from "./parts/carousel-track";
import { SingleItem } from "./parts/single-item";

interface MediaCarouselInnerProps extends MediaCarouselProps {
  ref?: React.Ref<MediaCarouselHandle>;
}

function MediaCarouselInner({
  items,
  variant,
  peekRatio: peekRatioProp = DEFAULT_PEEK_RATIO,
  aspect = "square",
  minRatio = DEFAULT_MIN_RATIO,
  maxRatio = DEFAULT_MAX_RATIO,
  loop,
  showIndicators = true,
  showNavButtons = true,
  showCounter = false,
  dir: dirProp,
  rtl,
  locale: localeProp,
  captionLines = 2,
  captionClassName,
  index,
  onIndexChange,
  defaultIndex,
  renderItem,
  onSlideChange,
  onDoubleTap,
  onMediaError,
  labels: labelsProp,
  className,
  slideClassName,
  ref,
}: MediaCarouselInnerProps) {
  const peekRatio = resolvePeekRatio(peekRatioProp);
  const labels = useMemo(() => resolveLabels(labelsProp), [labelsProp]);
  const locale = useMemo(() => resolveLocale(localeProp), [localeProp]);
  const formatter = useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const formatNumber = useCallback((n: number) => formatter.format(n), [formatter]);
  const recovery = useMediaRecovery(onMediaError);

  // `natural-clamped`: the first item's declared size, else its loaded natural size
  // (square until it loads). Keyed by id so a new first item starts over.
  const first = items[0];
  const [natural, setNatural] = useState<{ id: string; ratio: number } | null>(null);
  const declared = declaredRatio(first, minRatio, maxRatio);
  const needsNatural = aspect === "natural-clamped" && declared === null && !!first;
  const naturalRatio =
    natural && first && natural.id === first.id ? clampRatio(natural.ratio, 1, minRatio, maxRatio) : null;
  const firstId = first?.id;
  const onNaturalSize = useCallback(
    (width: number, height: number) => {
      if (!firstId || !width || !height) return;
      setNatural((prev) =>
        prev && prev.id === firstId && prev.ratio === width / height ? prev : { id: firstId, ratio: width / height },
      );
    },
    [firstId],
  );
  const frame = useMemo(
    () => frameFor(aspect, declared ?? naturalRatio),
    [aspect, declared, naturalRatio],
  );

  // `dir` wins; the deprecated `rtl` only when set; otherwise resolved from the element.
  const dir = dirProp ?? (rtl === undefined ? undefined : rtl ? "rtl" : "ltr");

  if (items.length === 0) return null;

  if (items.length === 1) {
    return (
      <SingleItem
        item={items[0]}
        renderItem={renderItem}
        onDoubleTap={onDoubleTap}
        labels={labels}
        frame={frame}
        recovery={recovery}
        onNaturalSize={needsNatural ? onNaturalSize : undefined}
        dir={dir}
        locale={locale}
        captionLines={captionLines}
        captionClassName={captionClassName}
        className={className}
        slideClassName={slideClassName}
      />
    );
  }

  return (
    <CarouselTrack
      ref={ref}
      items={items}
      variant={variant}
      peekRatio={peekRatio}
      frame={frame}
      loop={loop ?? true}
      showIndicators={showIndicators}
      showNavButtons={showNavButtons}
      showCounter={showCounter}
      dir={dir}
      locale={locale}
      captionLines={captionLines}
      captionClassName={captionClassName}
      formatNumber={formatNumber}
      index={index}
      defaultIndex={defaultIndex}
      onIndexChange={onIndexChange}
      renderItem={renderItem}
      onSlideChange={onSlideChange}
      onDoubleTap={onDoubleTap}
      recovery={recovery}
      onNaturalSize={needsNatural ? onNaturalSize : undefined}
      labels={labels}
      className={className}
      slideClassName={slideClassName}
    />
  );
}

const MediaCarousel = memo(MediaCarouselInner);
MediaCarousel.displayName = "MediaCarousel";

export { MediaCarousel };
export default MediaCarousel;

export { default as MediaCarousel } from "./media-carousel";

export type {
  MediaCarouselProps,
  MediaCarouselHandle,
  MediaCarouselLabels,
  ResolvedMediaCarouselLabels,
  MediaCarouselVariant,
  MediaCarouselAspect,
  MediaCarouselDirection,
  MediaItem,
  RenderItemContext,
  LinearAspect,
} from "./types";

export { defaultMediaCarouselLabels, DEFAULT_MEDIA_CAROUSEL_LABELS } from "./types";

// @ilinxa/media-carousel 0.4.0

import type { ReactNode } from "react";
// F-S1 lock: same-category cross-procomp via relative + specific-file path.
import type { VideoPlayerLabels } from "../video-player/types";

export type MediaCarouselVariant = "gallery" | "linear";

/** The fixed aspect ratios (the 0.2 set). */
export type LinearAspect = "square" | "video" | "portrait" | "auto";

/**
 * Slide frame ratio. `natural-clamped` = the first item's own ratio, clamped to
 * `[minRatio, maxRatio]` (width / height) — e.g. 3:4 → 4:5, 16:9 stays, 3:1 → 1.91:1.
 * 0.4.0: also any `"W:H"` with finite positive numbers (`"4:5"`, `"1.91:1"`), the
 * same strings media-editor and carousel-composer use. An invalid `"W:H"` falls back
 * to `"square"` (one dev warning).
 */
export type MediaCarouselAspect = LinearAspect | "natural-clamped" | `${number}:${number}`;

export type MediaCarouselDirection = "ltr" | "rtl";

/**
 * Discriminated union — strict shape.
 *
 * `caption` (0.4.0): short text shown under the slide's frame (outside the aspect box),
 * clamped to `captionLines` with a Show more toggle, `dir="auto"`. It is part of its
 * slide, so a screen reader reads it once, with that slide; it is not used as the
 * image's `alt` (give `alt` for that). No caption = no space taken.
 */
export type MediaItem =
  | {
      id: string;
      type: "image";
      url: string;
      alt?: string;
      caption?: string;
      /** Intrinsic size in px — reserves the frame before load and feeds `natural-clamped`. */
      width?: number;
      height?: number;
      /** Forwarded to the built-in `<img>`. */
      srcSet?: string;
      sizes?: string;
    }
  | {
      id: string;
      type: "video";
      url: string;
      /** 0.4.0: names the built-in player's `<video>` (otherwise `labels.video.videoLabel`). */
      alt?: string;
      caption?: string;
      poster?: string;
      /** Intrinsic size in px — feeds `natural-clamped` before the metadata loads. */
      width?: number;
      height?: number;
    };

export interface RenderItemContext {
  /** True when this slide is the currently centered/snapped slide. */
  isActive: boolean;
  /**
   * True while at least half of the carousel is in the viewport (always true on the server
   * and the first render). The built-in video plays only when `isActive && inView` — a custom
   * video renderer should use the same condition.
   */
  inView: boolean;
  /** Index of this slide in the items array. */
  index: number;
}

export interface MediaCarouselLabels {
  /** Default: "Media carousel". aria-label on the carousel region. */
  carouselLabel?: string;
  /** Default: "Previous slide". aria-label on the prev nav button. */
  previousSlide?: string;
  /** Default: "Next slide". aria-label on the next nav button. */
  nextSlide?: string;
  /**
   * Indicator dot name: `(position) => string`, position 1-based. Default `"Go to slide 2"`.
   * A string is the deprecated 0.2 form: a prefix, named `"{prefix} {n}"`.
   */
  goToSlide?: string | ((position: number) => string);
  /**
   * Slide name: `(position, total) => string`, position 1-based. Default `"Slide 2 of 5"`.
   * A string is the deprecated 0.2 template with `{index}` / `{total}` placeholders.
   */
  slideAriaLabel?: string | ((position: number, total: number) => string);
  /**
   * Visible counter chip (`showCounter`). `format` renders a number in `locale`.
   * Default `"2/5"`.
   */
  counter?: (position: number, total: number, format: (n: number) => string) => string;
  /** Default: "carousel". `aria-roledescription` of the region. */
  carouselRoleDescription?: string;
  /** Default: "slide". `aria-roledescription` of each slide. */
  slideRoleDescription?: string;
  /** 0.4.0. Default: "Show more". The caption's expand toggle. */
  captionShowMore?: string;
  /** 0.4.0. Default: "Show less". The caption's collapse toggle. */
  captionShowLess?: string;
  /**
   * 0.4.0. Labels for every built-in video player (play, mute, seek…), merged over
   * video-player's defaults. A video item's `alt` wins over `videoLabel`.
   */
  video?: VideoPlayerLabels;
}

/** Labels after merging over the defaults — every value present, value labels as functions. */
export interface ResolvedMediaCarouselLabels {
  carouselLabel: string;
  previousSlide: string;
  nextSlide: string;
  goToSlide: (position: number) => string;
  slideAriaLabel: (position: number, total: number) => string;
  counter: (position: number, total: number, format: (n: number) => string) => string;
  carouselRoleDescription: string;
  slideRoleDescription: string;
  captionShowMore: string;
  captionShowLess: string;
  /** Passed through as given (video-player merges its own defaults). */
  video?: VideoPlayerLabels;
}

export interface MediaCarouselProps {
  /** Items to render. Required. */
  items: MediaItem[];
  /** Variant — `gallery` (peek-scale) or `linear` (snap). Required. */
  variant: MediaCarouselVariant;

  // ─── Per-variant config ──────────────────────────────────────────
  /**
   * Gallery only: peek ratio per side (e.g., 0.075 = 7.5%). Default: 0.075. 0.4.0: sets
   * the slide width (`1 − 2 × peekRatio`) — before 0.4.0 slides were always 85 % wide. Clamped to
   * 0–0.45; a non-finite value uses 0.075 (one dev warning).
   */
  peekRatio?: number;
  /**
   * Slide frame ratio, for both variants and a single item. Default: "square".
   * In a gallery every slide uses the same frame (the first item's, for `natural-clamped`).
   */
  aspect?: MediaCarouselAspect;
  /** `natural-clamped` lower bound (width / height). Default: 4 / 5. */
  minRatio?: number;
  /** `natural-clamped` upper bound (width / height). Default: 1.91. */
  maxRatio?: number;

  // ─── Carousel behavior ───────────────────────────────────────────
  /** Loop slides. Default: items.length > 1. */
  loop?: boolean;
  /** Show indicator dots. Default: true. Always hidden when items.length <= 1. */
  showIndicators?: boolean;
  /**
   * Side nav buttons. Default: true. `"fine-pointer"` = only under a mouse / trackpad
   * (`(pointer: fine)`, resolved after mount). Always hidden when items.length <= 1.
   */
  showNavButtons?: boolean | "fine-pointer";
  /** Visible "2/5" chip. Default: false. */
  showCounter?: boolean;
  /**
   * Text direction. Default: the element's direction after mount (an ancestor `dir="rtl"`
   * works). Embla, arrow keys, chevrons, nav sides, peek and fades all follow it.
   */
  dir?: MediaCarouselDirection;
  /** @deprecated Use `dir="rtl"`. Ignored when `dir` is set. */
  rtl?: boolean;
  /**
   * BCP 47 locale for the counter numbers and (0.4.0) the built-in video players' time
   * text. Default: "en"; an invalid tag falls back to "en".
   */
  locale?: string;

  // ─── Captions (0.4.0) ────────────────────────────────────────────
  /** Lines a caption shows before its Show more toggle. Default: 2. */
  captionLines?: number;
  /** Extra classes for each caption's text element. */
  captionClassName?: string;

  // ─── Controlled index (opt-in) ───────────────────────────────────
  /**
   * Controlled slide index. When set, the prop wins on every render: a swipe calls
   * `onIndexChange` and settles back unless the parent adopts the new index.
   */
  index?: number;
  /** Fires when the user (or the handle) moves to another slide. */
  onIndexChange?: (index: number) => void;
  /** Starting slide when uncontrolled. Default: 0. */
  defaultIndex?: number;

  // ─── Customization ───────────────────────────────────────────────
  /** Custom per-slide renderer — bypasses both built-in handlers. */
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;

  // ─── Callbacks ───────────────────────────────────────────────────
  /** Fires on Embla `select` event (post-snap; once per slide commit). */
  onSlideChange?: (index: number) => void;
  /** Fires on double-tap of any slide. Unified for image + video items. */
  onDoubleTap?: (item: MediaItem, index: number) => void;
  /**
   * A built-in image or video failed to load (an expired signed URL…). Resolve a new URL to
   * retry once; a second failure for the same item does not call again. A new `url` from the
   * host resets it. A video shows its loading state meanwhile and resumes at the same time.
   */
  onMediaError?: (item: MediaItem) => Promise<string | void> | string | void;

  // ─── i18n ────────────────────────────────────────────────────────
  /** Localized labels. Defaults are English; an `undefined` value keeps the default. */
  labels?: MediaCarouselLabels;

  // ─── Style overrides ─────────────────────────────────────────────
  /**
   * Override classes for the wrapping <div>. CSS variables: `--media-carousel-fade` (edge
   * fade colour, default `var(--background)`), `--media-carousel-inactive-blur` (default `1px`).
   */
  className?: string;
  /** Override classes per slide wrapper. */
  slideClassName?: string;
}

export interface MediaCarouselHandle {
  /** Scroll to a specific slide (0-indexed). */
  scrollTo: (index: number) => void;
  /** Scroll to previous slide. */
  scrollPrev: () => void;
  /** Scroll to next slide. */
  scrollNext: () => void;
  /** Get the currently active slide index. */
  getCurrentIndex: () => number;
}

/** Default English labels — exported for consumer composition. */
export const defaultMediaCarouselLabels: ResolvedMediaCarouselLabels = {
  carouselLabel: "Media carousel",
  previousSlide: "Previous slide",
  nextSlide: "Next slide",
  goToSlide: (position) => `Go to slide ${position}`,
  slideAriaLabel: (position, total) => `Slide ${position} of ${total}`,
  counter: (position, total, format) => `${format(position)}/${format(total)}`,
  carouselRoleDescription: "carousel",
  slideRoleDescription: "slide",
  captionShowMore: "Show more",
  captionShowLess: "Show less",
};

/**
 * @deprecated The 0.2 string labels — use `defaultMediaCarouselLabels`. Still accepted as
 * `labels`.
 */
export const DEFAULT_MEDIA_CAROUSEL_LABELS = {
  carouselLabel: "Media carousel",
  previousSlide: "Previous slide",
  nextSlide: "Next slide",
  goToSlide: "Go to slide",
  slideAriaLabel: "Slide {index} of {total}",
} as const satisfies MediaCarouselLabels;

"use client";

import { cn } from "@/lib/utils";
// Cross-category (data/) static import: the registry rewriter handles it, the registry.json item
// declares `@ilinxa/expandable-text`.
import { ExpandableText } from "@/registry/components/data/expandable-text/expandable-text";
import type { ResolvedMediaCarouselLabels } from "../types";

interface SlideCaptionProps {
  caption: string;
  lines: number;
  className?: string;
  /** Only the active slide's toggle is reachable; an inactive slide is `aria-hidden`. */
  active: boolean;
  labels: Pick<ResolvedMediaCarouselLabels, "captionShowMore" | "captionShowLess">;
}

/**
 * The caption under a slide's frame. Lives inside the slide's `role="group"`, so it is read once
 * with its slide. `inert` on inactive slides keeps the Show more toggle out of the tab order
 * (nothing focusable under `aria-hidden`).
 */
export function SlideCaption({ caption, lines, className, active, labels }: SlideCaptionProps) {
  return (
    <div
      inert={!active}
      className={cn("px-1 pt-2 motion-safe:transition-opacity motion-safe:duration-300", !active && "opacity-60")}
    >
      <ExpandableText
        content={caption}
        maxLines={lines}
        dir="auto"
        labels={{ showMore: labels.captionShowMore, showLess: labels.captionShowLess }}
        contentClassName={cn("text-sm text-foreground", className)}
      />
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { useRef } from "react";
import { cn } from "@/lib/utils";
// F-S1 lock: same-category cross-procomp via relative + specific-file path.
import { useDoubleTap } from "../../video-player/hooks/use-double-tap";
import { useInView } from "../hooks/use-environment";
import type { MediaRecovery } from "../hooks/use-media-recovery";
import type { FrameStyle } from "../lib/aspect";
import { SlideCaption } from "./slide-caption";
import { SlideRenderer } from "./slide-renderer";
import type {
  MediaItem,
  RenderItemContext,
  ResolvedMediaCarouselLabels,
} from "../types";

interface SingleItemProps {
  item: MediaItem;
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;
  onDoubleTap?: (item: MediaItem, index: number) => void;
  labels: ResolvedMediaCarouselLabels;
  frame: FrameStyle;
  recovery: MediaRecovery;
  onNaturalSize?: (width: number, height: number) => void;
  /** Explicit direction; written on the root so a `renderItem` follows it. */
  dir?: "ltr" | "rtl";
  locale: string;
  captionLines: number;
  captionClassName?: string;
  className?: string;
  slideClassName?: string;
}

/**
 * Single-item shortcut — bypass Embla entirely.
 *
 * Lives in its own component so `useDoubleTap` is called unconditionally
 * within it (own hook count, distinct from `<CarouselTrack>`). Switching
 * between single-item and carousel modes happens via component swap at
 * the root, not conditional hook calls.
 */
export function SingleItem({
  item,
  renderItem,
  onDoubleTap,
  labels,
  frame,
  recovery,
  onNaturalSize,
  dir,
  locale,
  captionLines,
  captionClassName,
  className,
  slideClassName,
}: SingleItemProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const inView = useInView(rootRef);
  // Images: double tap on the wrapper. Videos: the player owns it, so its single tap waits out the
  // double-tap window instead of toggling playback twice (video-player VP7) — as in CarouselTrack.
  const isVideo = item.type === "video" && !renderItem;
  const handleDoubleTap = useDoubleTap(
    onDoubleTap && !isVideo ? () => onDoubleTap(item, 0) : undefined,
  );

  return (
    <div
      ref={rootRef}
      role="group"
      dir={dir}
      className={cn("relative", !item.caption && "overflow-hidden bg-muted", className)}
      aria-label={labels.carouselLabel}
    >
      {/* With a caption, the clip + tint move to the frame so the caption sits outside them. */}
      <div
        className={item.caption ? "relative overflow-hidden rounded-[inherit] bg-muted" : undefined}
        onClick={handleDoubleTap}
      >
        <SlideRenderer
          item={item}
          ctx={{ isActive: true, inView, index: 0 }}
          renderItem={renderItem}
          // Images are handled at wrapper level; don't double-fire.
          onDoubleTap={isVideo ? onDoubleTap : undefined}
          frame={frame}
          recovery={recovery}
          onNaturalSize={onNaturalSize}
          slideClassName={slideClassName}
          locale={locale}
          videoLabels={labels.video}
        />
      </div>
      {item.caption ? (
        <SlideCaption
          caption={item.caption}
          lines={captionLines}
          className={captionClassName}
          active
          labels={labels}
        />
      ) : null}
    </div>
  );
}

"use client";

import type { CSSProperties, KeyboardEvent as ReactKeyboardEvent, ReactNode, Ref } from "react";
import {
  useCallback,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { cn } from "@/lib/utils";
// F-S1 lock: same-category cross-procomp via relative + specific-file path.
import { useDoubleTap } from "../../video-player/hooks/use-double-tap";
import { useDirection } from "../hooks/use-direction";
import { useEmblaWithState } from "../hooks/use-embla-with-state";
import { useFinePointer, useInView } from "../hooks/use-environment";
import type { MediaRecovery } from "../hooks/use-media-recovery";
import type { FrameStyle } from "../lib/aspect";
import type { EmblaCarouselType } from "embla-carousel";
import type {
  MediaCarouselDirection,
  MediaCarouselHandle,
  MediaCarouselVariant,
  MediaItem,
  RenderItemContext,
  ResolvedMediaCarouselLabels,
} from "../types";
import { IndicatorDots } from "./indicator-dots";
import { NavButtons } from "./nav-buttons";
import { SlideCaption } from "./slide-caption";
import { SlideRenderer } from "./slide-renderer";

interface CarouselTrackProps {
  items: MediaItem[];
  variant: MediaCarouselVariant;
  peekRatio: number;
  frame: FrameStyle;
  loop: boolean;
  showIndicators: boolean;
  showNavButtons: boolean | "fine-pointer";
  showCounter: boolean;
  /** Explicit direction (`dir`, or the deprecated `rtl`); otherwise resolved after mount. */
  dir?: MediaCarouselDirection;
  locale: string;
  captionLines: number;
  captionClassName?: string;
  formatNumber: (n: number) => string;
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;
  onSlideChange?: (index: number) => void;
  onDoubleTap?: (item: MediaItem, index: number) => void;
  recovery: MediaRecovery;
  onNaturalSize?: (width: number, height: number) => void;
  labels: ResolvedMediaCarouselLabels;
  className?: string;
  slideClassName?: string;
  ref?: Ref<MediaCarouselHandle>;
}

interface SlideProps {
  item: MediaItem;
  index: number;
  total: number;
  isActive: boolean;
  inView: boolean;
  isFirst: boolean;
  isLast: boolean;
  /** Embla's EFFECTIVE loop (it drops loop when the slides can't fill it). */
  loop: boolean;
  variant: MediaCarouselVariant;
  peekRatio: number;
  frame: FrameStyle;
  locale: string;
  captionLines: number;
  captionClassName?: string;
  /** Shows the counter chip inside this (active) slide's frame. */
  counter?: string;
  slideRef: (el: HTMLDivElement | null) => void;
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;
  onDoubleTap?: (item: MediaItem, index: number) => void;
  /** Click on a peeking (inactive) neighbour. */
  onSelectNeighbour: (index: number) => void;
  recovery: MediaRecovery;
  onNaturalSize?: (width: number, height: number) => void;
  labels: ResolvedMediaCarouselLabels;
  slideClassName?: string;
}

const clampIndex = (i: number, total: number) =>
  Math.min(Math.max(0, Math.trunc(Number.isFinite(i) ? i : 0)), Math.max(0, total - 1));

/** video-player reads it for its bottom control row; dots sit at 0.75rem + 6px. */
const DOTS_CLEARANCE = { "--video-player-controls-bottom": "1.75rem" } as CSSProperties;

const INTERACTIVE =
  'button, a[href], input, select, textarea, video, [contenteditable="true"], [role="slider"], [role="button"], [role="menu"], [role="menuitem"], [role="menuitemradio"], [role="listbox"], [role="combobox"], [role="spinbutton"]';

/**
 * Embla starts a drag on any `mousedown` / `touchstart` except form fields: scrubbing a video's
 * seek bar (or using a menu) inside a slide would also drag the carousel. Swiping on the video
 * itself still drags.
 */
const allowSlideDrag = (_api: unknown, evt: MouseEvent | TouchEvent) =>
  !(evt.target instanceof Element && evt.target.closest('[role="slider"], [role="menu"]'));

/**
 * The key came from an interactive element inside a SLIDE (a video's controls, a button, a field
 * in `renderItem` content) — not from the region itself or the carousel's own chevrons / dots,
 * whose arrow keys keep moving the carousel as before.
 */
function isFromInteractiveDescendant(e: ReactKeyboardEvent<HTMLElement>): boolean {
  const target = e.target;
  if (!(target instanceof Element) || target === e.currentTarget) return false;
  const control = target.closest(INTERACTIVE);
  return (
    control !== null &&
    control !== e.currentTarget &&
    e.currentTarget.contains(control) &&
    control.closest("[data-media-carousel-slide]") !== null
  );
}

function Slide({
  item,
  index,
  total,
  isActive,
  inView,
  isFirst,
  isLast,
  loop,
  variant,
  peekRatio,
  frame,
  locale,
  captionLines,
  captionClassName,
  counter,
  slideRef,
  renderItem,
  onDoubleTap,
  onSelectNeighbour,
  recovery,
  onNaturalSize,
  labels,
  slideClassName,
}: SlideProps) {
  // Image items: attach double-tap on the slide wrapper. Video items: handled
  // inside SlideRenderer via VideoPlayer's onDoubleTap. Both fire the same
  // unified onDoubleTap callback.
  const imageDoubleTap = useDoubleTap(
    item.type === "image" && onDoubleTap
      ? () => onDoubleTap(item, index)
      : undefined,
  );

  // An inactive slide's content is `inert` (out of the tab order and the accessibility tree,
  // and not a pointer target), so a click on it lands on this wrapper — which scrolls to it.
  // `aria-hidden` keeps the wrapper itself out of the tree too.
  const handleClick = isActive
    ? item.type === "image"
      ? imageDoubleTap
      : undefined
    : () => onSelectNeighbour(index);

  const content = (
    <SlideRenderer
      item={item}
      ctx={{ isActive, inView, index }}
      renderItem={renderItem}
      onDoubleTap={onDoubleTap}
      frame={frame}
      recovery={recovery}
      onNaturalSize={onNaturalSize}
      slideClassName={slideClassName}
      locale={locale}
      videoLabels={labels.video}
    />
  );

  // Inside the active frame (top-end), so it can never sit over a peeking neighbour.
  const chip = counter ? (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute end-3 top-3 z-10 rounded-full bg-background/80 px-2 py-0.5 text-xs font-medium tabular-nums text-foreground"
    >
      {counter}
    </div>
  ) : null;
  // Under the frame, inside the slide group: read once with its slide.
  const caption = item.caption ? (
    <SlideCaption
      caption={item.caption}
      lines={captionLines}
      className={captionClassName}
      active={isActive}
      labels={labels}
    />
  ) : null;

  const a11y = {
    role: "group",
    "aria-roledescription": labels.slideRoleDescription,
    "aria-label": labels.slideAriaLabel(index + 1, total),
    "aria-hidden": isActive ? undefined : true,
    "data-media-carousel-slide": "",
  } as const;

  if (variant === "gallery") {
    // Edge peek padding only matters when NOT looping. Under loop, Embla
    // positions slides so first/last in view != first/last in source —
    // applying edge padding to the source first/last would create asymmetric
    // slide widths that break Embla's loop math.
    const edgePeekPercent = peekRatio * 100;
    return (
      <div
        {...a11y}
        ref={slideRef}
        className={cn("min-w-0 mx-1", !isActive && "cursor-pointer")}
        style={{
          // Slide width = the viewport minus a peek per side (85 % at the default 0.075).
          flex: `0 0 ${Math.round((1 - 2 * peekRatio) * 1e4) / 100}%`,
          marginInlineStart: !loop && isFirst ? `${edgePeekPercent}%` : undefined,
          marginInlineEnd: !loop && isLast ? `${edgePeekPercent}%` : undefined,
        }}
        onClick={handleClick}
      >
        <div
          inert={!isActive}
          className={cn(
            "relative overflow-hidden rounded-lg motion-safe:transition-all motion-safe:duration-300",
            isActive
              ? "scale-100 opacity-100"
              : "scale-95 opacity-60 blur-(--media-carousel-inactive-blur,1px)",
          )}
        >
          {content}
          {chip}
        </div>
        {caption}
      </div>
    );
  }

  // Linear: full-width slide, no peek, no scale.
  return (
    <div {...a11y} ref={slideRef} className="min-w-0 flex-[0_0_100%]" onClick={handleClick}>
      <div inert={!isActive} className="relative">
        {content}
        {chip}
      </div>
      {caption}
    </div>
  );
}

/**
 * Embla rebuilds itself with `loop: false` when the slides can't fill the loop (2 slides at 85 %):
 * the engine's own options, not ours, say whether it really loops
 * (node_modules/embla-carousel/esm/embla-carousel.esm.js:1528, createEngine).
 */
const readEngineLoop = (api: EmblaCarouselType | null, requested: boolean) =>
  requested && (api ? api.internalEngine().options.loop : true);

export function CarouselTrack({
  items,
  variant,
  peekRatio,
  frame,
  loop,
  showIndicators,
  showNavButtons,
  showCounter,
  dir: dirProp,
  locale,
  captionLines,
  captionClassName,
  formatNumber,
  index: indexProp,
  defaultIndex,
  onIndexChange,
  renderItem,
  onSlideChange,
  onDoubleTap,
  recovery,
  onNaturalSize,
  labels,
  className,
  slideClassName,
  ref: forwardedRef,
}: CarouselTrackProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const dir = useDirection(rootRef, dirProp);
  const inView = useInView(rootRef);
  const finePointer = useFinePointer();
  const total = items.length;

  const controlled = indexProp !== undefined;
  const target = controlled ? clampIndex(indexProp, total) : undefined;
  // Embla's start slide — read once; later moves go through scrollTo.
  const [startIndex] = useState(() => clampIndex(indexProp ?? defaultIndex ?? 0, total));

  // Memoize Embla options — useEmblaCarousel re-initializes on options identity change.
  // Under loop, Embla force-disables containScroll; we don't set it explicitly there.
  // Under linear+no-loop, we trim duplicate edge snaps so prev/next stop cleanly.
  const emblaOptions = useMemo(
    () => ({
      align: variant === "gallery" ? ("center" as const) : ("start" as const),
      ...(variant === "linear" && !loop
        ? { containScroll: "trimSnaps" as const }
        : {}),
      loop,
      direction: dir,
      startIndex,
      watchDrag: allowSlideDrag,
    }),
    [variant, loop, dir, startIndex],
  );

  // The controlled index, read by the select handler without re-subscribing.
  const targetRef = useRef(target);
  useEffect(() => {
    targetRef.current = target;
  });

  const handleSelect = useCallback(
    (i: number) => {
      onSlideChange?.(i);
      // Controlled: only a move away from the prop is a request (the settle-back and a
      // prop-driven scroll land on the prop and stay silent).
      if (targetRef.current === undefined || i !== targetRef.current) onIndexChange?.(i);
    },
    [onSlideChange, onIndexChange],
  );

  const { ref, api, currentIndex, scrollTo, scrollPrev, scrollNext } =
    useEmblaWithState({ ...emblaOptions, onSelect: handleSelect });

  // Controlled: the prop wins. Scroll to it when it changes, and settle back to it after a
  // swipe the parent did not adopt (on `settle`, so a drag in progress is never yanked), and
  // after a re-init.
  useEffect(() => {
    if (!controlled || !api) return;
    const correct = () => {
      const t = targetRef.current;
      if (t !== undefined && api.selectedScrollSnap() !== t) api.scrollTo(t);
    };
    correct();
    api.on("settle", correct);
    api.on("reInit", correct);
    return () => {
      api.off("settle", correct);
      api.off("reInit", correct);
    };
  }, [controlled, api, target]);

  const shownIndex = target ?? currentIndex;

  // The loop Embla really runs (see readEngineLoop). Not looping => edge margins on the first /
  // last slide, and Prev / Next stop at the ends.
  const subscribeReInit = useCallback(
    (onChange: () => void) => {
      if (!api) return () => {};
      api.on("reInit", onChange);
      return () => {
        api.off("reInit", onChange);
      };
    },
    [api],
  );
  const effectiveLoop = useSyncExternalStore(
    subscribeReInit,
    () => readEngineLoop(api, loop),
    () => loop,
  );
  // Embla measured the slides before the edge margins existed (loop true -> false) and keeps stale
  // sizes once they go away (false -> true, e.g. 2 -> 4 items): re-init on any change of the
  // effective loop after the first run. A re-init that lands on the same value stops here.
  const lastLoop = useRef<boolean | null>(null);
  useEffect(() => {
    if (!api) return;
    const prev = lastLoop.current;
    lastLoop.current = effectiveLoop;
    if (prev === null ? loop && !effectiveLoop : prev !== effectiveLoop) api.reInit();
  }, [api, loop, effectiveLoop]);
  const canPrev = effectiveLoop || (api ? api.canScrollPrev() : shownIndex > 0);
  const canNext = effectiveLoop || (api ? api.canScrollNext() : shownIndex < total - 1);

  // Captions: each slide has its own height; the viewport follows the active slide's, and the
  // nav buttons / edge fades centre on the media frame (not frame + caption).
  const hasCaptions = useMemo(() => items.some((it) => !!it.caption), [items]);
  const slideEls = useRef<Array<HTMLDivElement | null>>([]);
  const [heights, setHeights] = useState<{ slide: number; frame: number } | null>(null);
  const activeId = items[shownIndex]?.id;
  useLayoutEffect(() => {
    // Drop refs of slides that no longer exist (a detached node would be observed otherwise).
    slideEls.current.length = total;
    if (!hasCaptions) return;
    const slide = slideEls.current[shownIndex];
    if (!slide) return;
    const frameEl = slide.firstElementChild as HTMLElement | null;
    const measure = () => {
      const slideH = slide.offsetHeight;
      if (slideH <= 0) return;
      const frameH = frameEl?.offsetHeight || slideH;
      setHeights((prev) =>
        prev && prev.slide === slideH && prev.frame === frameH ? prev : { slide: slideH, frame: frameH },
      );
    };
    // First paint: read before the browser paints. Without ResizeObserver this one-shot read per
    // shown slide is all there is.
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(measure);
    ro.observe(slide);
    if (frameEl) ro.observe(frameEl);
    return () => ro.disconnect();
    // activeId: a replaced item at the same index is a new node, which must be observed.
  }, [hasCaptions, shownIndex, activeId, total]);
  const measured = hasCaptions ? heights : null;

  // Stable ref-mirror for the shown index — keeps imperative handle identity
  // stable across slide changes. Ref write inside passive useEffect.
  const currentIndexRef = useRef(shownIndex);
  useEffect(() => {
    currentIndexRef.current = shownIndex;
  });

  useImperativeHandle(
    forwardedRef,
    () => ({
      scrollTo,
      scrollPrev,
      scrollNext,
      getCurrentIndex: () => currentIndexRef.current,
    }),
    [scrollTo, scrollPrev, scrollNext],
  );

  // A click that ends a drag never reaches a slide: Embla stops it in the capture phase on the
  // slide container.
  const selectNeighbour = scrollTo;

  // Gallery variant gets soft edge fades (mirrors kasder UX). Linear variant doesn't
  // — full-width slides have no peek to soften.
  const showEdgeGradients = variant === "gallery";
  const navButtonsVisible =
    showNavButtons === "fine-pointer" ? finePointer : showNavButtons;

  // Keyboard nav — APG carousel pattern: ArrowLeft/Right scroll prev/next
  // (direction-aware), Home/End jump to first/last. Wired on the focusable region
  // wrapper so users tabbing into the carousel get arrow-key control without
  // first focusing a child slide.
  const handleKeyDown = useCallback(
    (e: ReactKeyboardEvent<HTMLDivElement>) => {
      // Keys belong to the slide's own controls (a video's seek bar, a button, a form field) —
      // already handled, or from an interactive element inside the region (review R-06).
      if (e.defaultPrevented || isFromInteractiveDescendant(e)) return;
      const rtl = dir === "rtl";
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        if (rtl) scrollNext();
        else scrollPrev();
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        if (rtl) scrollPrev();
        else scrollNext();
      } else if (e.key === "Home") {
        e.preventDefault();
        scrollTo(0);
      } else if (e.key === "End") {
        e.preventDefault();
        scrollTo(total - 1);
      }
    },
    [dir, scrollPrev, scrollNext, scrollTo, total],
  );

  return (
    <div
      ref={rootRef}
      role="region"
      aria-roledescription={labels.carouselRoleDescription}
      aria-label={labels.carouselLabel}
      // Only an explicit direction is written, so an inherited one is never overridden.
      dir={dirProp}
      data-dir={dirProp}
      tabIndex={0}
      onKeyDown={handleKeyDown}
      className={cn(
        "group/media-carousel relative outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-md",
        className,
      )}
      // Lift a video slide's control row above the indicator dots (video-player 0.3 has a full-width seek bar).
      // With captions the dots sit below the slides, not over the video.
      style={showIndicators && !hasCaptions ? DOTS_CLEARANCE : undefined}
    >
      {/* The media area's positioning box: without captions it is the whole carousel. */}
      <div className="relative">
        <div
          className={cn("overflow-hidden", measured && "motion-safe:transition-[height] motion-safe:duration-300")}
          style={measured ? { height: measured.slide } : undefined}
          ref={ref}
        >
          <div className={cn("flex", hasCaptions && "items-start")}>
            {items.map((item, index) => (
              <Slide
                key={item.id}
                item={item}
                index={index}
                total={total}
                isActive={index === shownIndex}
                inView={inView}
                isFirst={index === 0}
                isLast={index === total - 1}
                loop={effectiveLoop}
                variant={variant}
                peekRatio={peekRatio}
                frame={frame}
                locale={locale}
                captionLines={captionLines}
                captionClassName={captionClassName}
                counter={
                  showCounter && index === shownIndex
                    ? labels.counter(shownIndex + 1, total, formatNumber)
                    : undefined
                }
                slideRef={(el) => {
                  slideEls.current[index] = el;
                }}
                renderItem={renderItem}
                onDoubleTap={onDoubleTap}
                onSelectNeighbour={selectNeighbour}
                recovery={recovery}
                onNaturalSize={index === 0 ? onNaturalSize : undefined}
                labels={labels}
                slideClassName={slideClassName}
              />
            ))}
          </div>
        </div>

        {showEdgeGradients ? (
          <>
            <div
              aria-hidden="true"
              className="pointer-events-none absolute inset-y-0 start-0 z-5 w-12 bg-linear-to-r rtl:bg-linear-to-l group-data-[dir=ltr]/media-carousel:bg-linear-to-r from-(--media-carousel-fade,var(--background)) to-transparent"
              style={measured ? { height: measured.frame, bottom: "auto" } : undefined}
            />
            <div
              aria-hidden="true"
              className="pointer-events-none absolute inset-y-0 end-0 z-5 w-12 bg-linear-to-l rtl:bg-linear-to-r group-data-[dir=ltr]/media-carousel:bg-linear-to-l from-(--media-carousel-fade,var(--background)) to-transparent"
              style={measured ? { height: measured.frame, bottom: "auto" } : undefined}
            />
          </>
        ) : null}

        {navButtonsVisible && (
          <NavButtons
            scrollPrev={scrollPrev}
            scrollNext={scrollNext}
            labels={labels}
            canPrev={canPrev}
            canNext={canNext}
            centerY={measured ? measured.frame / 2 : undefined}
          />
        )}

        {showIndicators && !hasCaptions && (
          <IndicatorDots
            total={total}
            currentIndex={shownIndex}
            scrollTo={scrollTo}
            labels={labels}
          />
        )}
      </div>

      {showIndicators && hasCaptions && (
        <IndicatorDots
          total={total}
          currentIndex={shownIndex}
          scrollTo={scrollTo}
          labels={labels}
          inFlow
        />
      )}
    </div>
  );
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { useEffect, useMemo, useRef } from "react";
import { cn } from "@/lib/utils";
// F-S1 lock: same-category cross-procomp via relative + specific-file path.
import { VideoPlayer } from "../../video-player/video-player";
import type { MediaRecovery } from "../hooks/use-media-recovery";
import type { FrameStyle } from "../lib/aspect";
import type { VideoPlayerLabels } from "../../video-player/types";
import type { MediaItem, RenderItemContext } from "../types";

interface SlideRendererProps {
  item: MediaItem;
  ctx: RenderItemContext;
  renderItem?: (item: MediaItem, ctx: RenderItemContext) => ReactNode;
  onDoubleTap?: (item: MediaItem, index: number) => void;
  /** Frame ratio (class or inline `aspect-ratio`), resolved by the root. */
  frame: FrameStyle;
  recovery: MediaRecovery;
  /** Set when the root still needs this item's natural size (`natural-clamped`, no dimensions). */
  onNaturalSize?: (width: number, height: number) => void;
  slideClassName?: string;
  /** BCP 47 locale for the built-in video player's time text. */
  locale?: string;
  /** `labels.video`, merged over the player defaults. */
  videoLabels?: VideoPlayerLabels;
}

/**
 * Renders a single slide. Three paths:
 *   1. `renderItem` provided → consumer takes over.
 *   2. `item.type === "image"` → built-in <img> handler.
 *   3. `item.type === "video"` → built-in <VideoPlayer>; plays only while `isActive && inView`.
 *
 * The video handler is a deliberate cross-folder import — see Q-P1 in the plan
 * doc and the project memory note on the refined sealed-folder rule.
 */
export function SlideRenderer({
  item,
  ctx,
  renderItem,
  onDoubleTap,
  frame,
  recovery,
  onNaturalSize,
  slideClassName,
  locale,
  videoLabels,
}: SlideRendererProps) {
  const frameRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);
  const src = recovery.urlFor(item);
  const reportError = recovery.onError;
  // A video item's `alt` names its player and wins over `labels.video.videoLabel`.
  const alt = item.type === "video" ? item.alt : undefined;
  const playerLabels = useMemo<VideoPlayerLabels | undefined>(
    () => (alt ? { ...videoLabels, videoLabel: alt } : videoLabels),
    [videoLabels, alt],
  );

  // An image that finished (or failed) before hydration — or was already loaded when it became
  // the first item — fires no event the handlers can see: read its state instead.
  useEffect(() => {
    const img = imgRef.current;
    if (!img || !img.complete || !img.getAttribute("src")) return;
    if (img.naturalWidth > 0) {
      onNaturalSize?.(img.naturalWidth, img.naturalHeight);
      return;
    }
    // Width 0 is also a loaded SVG without intrinsic size — only a failed decode is broken.
    if (typeof img.decode !== "function") return;
    // (Asking twice is impossible: recovery asks once per item + URL.)
    img.decode().catch(() => reportError(item));
  },[src, item, onNaturalSize, reportError]);

  const frameClass = cn(frame.className, "overflow-hidden", slideClassName);
  const frameStyle: CSSProperties | undefined = frame.style;

  if (renderItem) {
    return (
      <div className={frameClass} style={frameStyle}>
        {renderItem(item, ctx)}
      </div>
    );
  }

  if (item.type === "image") {
    return (
      <div className={frameClass} style={frameStyle}>
        <img
          ref={imgRef}
          src={src}
          srcSet={src === item.url ? item.srcSet : undefined}
          sizes={src === item.url ? item.sizes : undefined}
          width={item.width}
          height={item.height}
          alt={item.alt ?? ""}
          loading="lazy"
          decoding="async"
          className="h-full w-full object-cover"
          onLoad={
            onNaturalSize
              ? (e) => onNaturalSize(e.currentTarget.naturalWidth, e.currentTarget.naturalHeight)
              : undefined
          }
          onError={() => recovery.onError(item)}
        />
      </div>
    );
  }

  return (
    <div ref={frameRef} className={frameClass} style={frameStyle}>
      <VideoPlayer
        src={src}
        poster={item.poster}
        locale={locale}
        labels={playerLabels}
        isActive={ctx.isActive && ctx.inView}
        onDoubleTap={
          onDoubleTap ? () => onDoubleTap(item, ctx.index) : undefined
        }
        onLoadedMetadata={
          onNaturalSize
            ? () => {
                const video = frameRef.current?.querySelector("video");
                if (video) onNaturalSize(video.videoWidth, video.videoHeight);
              }
            : undefined
        }
        // Through the player, so it shows buffering while the URL refreshes and resumes at the
        // same time (VP4). The carousel still asks once per item + URL.
        onMediaError={recovery.enabled ? () => recovery.request(item) : undefined}
      />
    </div>
  );
}

"use client";

import { ChevronLeft, ChevronRight } from "lucide-react";
import { Button } from "@/components/ui/button";

interface NavButtonsProps {
  scrollPrev: () => void;
  scrollNext: () => void;
  labels: { previousSlide: string; nextSlide: string };
  /** False at the first slide when the carousel is not (effectively) looping. Default true. */
  canPrev?: boolean;
  /** False at the last slide when the carousel is not (effectively) looping. Default true. */
  canNext?: boolean;
  /** Vertical centre in px, measured from the top; default is the middle of the whole carousel. */
  centerY?: number;
}

/**
 * A disabled end stays focusable (`aria-disabled`, no-op click, disabled look) so focus is not
 * dropped to <body> and a click cannot fall through to the slide beneath.
 *
 * Previous sits at the inline start, next at the inline end; the chevrons flip under `rtl:`
 * (the track sets `dir` on its root when the direction comes from a prop). An explicit
 * `dir="ltr"` inside an RTL page undoes the flip: Tailwind `rtl:` also matches any descendant
 * of a `[dir=rtl]` ancestor, so the root carries `data-dir` for the override.
 */
export function NavButtons({
  scrollPrev,
  scrollNext,
  labels,
  canPrev = true,
  canNext = true,
  centerY,
}: NavButtonsProps) {
  const style = centerY === undefined ? undefined : { top: centerY };
  return (
    <>
      <Button
        type="button"
        variant="secondary"
        size="icon"
        className="absolute top-1/2 start-2 z-10 h-8 w-8 -translate-y-1/2 rounded-full opacity-80 hover:opacity-100 aria-disabled:cursor-default aria-disabled:opacity-40 aria-disabled:hover:opacity-40 rtl:rotate-180 group-data-[dir=ltr]/media-carousel:rotate-0"
        style={style}
        aria-disabled={!canPrev ? "true" : undefined}
        onClick={canPrev ? scrollPrev : undefined}
        aria-label={labels.previousSlide}
      >
        <ChevronLeft className="h-4 w-4" aria-hidden="true" />
      </Button>
      <Button
        type="button"
        variant="secondary"
        size="icon"
        className="absolute top-1/2 end-2 z-10 h-8 w-8 -translate-y-1/2 rounded-full opacity-80 hover:opacity-100 aria-disabled:cursor-default aria-disabled:opacity-40 aria-disabled:hover:opacity-40 rtl:rotate-180 group-data-[dir=ltr]/media-carousel:rotate-0"
        style={style}
        aria-disabled={!canNext ? "true" : undefined}
        onClick={canNext ? scrollNext : undefined}
        aria-label={labels.nextSlide}
      >
        <ChevronRight className="h-4 w-4" aria-hidden="true" />
      </Button>
    </>
  );
}

