import { cn } from "@/lib/utils";

interface IndicatorDotsProps {
  total: number;
  currentIndex: number;
  scrollTo: (index: number) => void;
  labels: { goToSlide: (position: number) => string };
  /** In normal flow below the slides (captions present) instead of overlaid on the media. */
  inFlow?: boolean;
}

export function IndicatorDots({
  total,
  currentIndex,
  scrollTo,
  labels,
  inFlow = false,
}: IndicatorDotsProps) {
  return (
    <div
      className={cn(
        "flex gap-1.5",
        inFlow ? "justify-center pt-2" : "absolute bottom-3 left-1/2 z-10 -translate-x-1/2",
      )}
    >
      {Array.from({ length: total }, (_, i) => {
        const isActive = i === currentIndex;
        return (
          <button
            key={i}
            type="button"
            onClick={() => scrollTo(i)}
            aria-label={labels.goToSlide(i + 1)}
            aria-current={isActive ? "true" : undefined}
            className={cn(
              "h-1.5 rounded-full motion-safe:transition-all motion-safe:duration-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              isActive
                ? "w-4 bg-primary"
                : "w-1.5 bg-primary/40 hover:bg-primary/60",
            )}
          />
        );
      })}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useSyncExternalStore } from "react";
import useEmblaCarousel from "embla-carousel-react";
import type {
  EmblaCarouselType,
  EmblaOptionsType,
} from "embla-carousel";

export interface UseEmblaWithStateOptions extends EmblaOptionsType {
  /** Fires on slide change. Does NOT fire on initial mount-sync. */
  onSelect?: (index: number) => void;
}

export interface UseEmblaWithStateResult {
  ref: (node: HTMLElement | null) => void;
  api: EmblaCarouselType | null;
  currentIndex: number;
  scrollTo: (index: number) => void;
  scrollPrev: () => void;
  scrollNext: () => void;
}

/**
 * Wraps `useEmblaCarousel` with currentIndex state via `useSyncExternalStore`
 * (avoids `setState`-in-effect lint violations) and lifecycle callbacks.
 *
 * **Mount-sync semantics:** `currentIndex` syncs to Embla's initial snap
 * automatically on mount. The user's `onSelect` callback does NOT fire on
 * the mount-sync — only on real slide changes (tracked via `isFirstFireRef`).
 *
 * `startIndex` is also the server / pre-init snapshot, so a non-zero start hydrates cleanly.
 *
 * Embla options should be memoized by the caller (Embla re-initializes on
 * options-object identity change).
 */
export function useEmblaWithState({
  onSelect,
  ...emblaOptions
}: UseEmblaWithStateOptions): UseEmblaWithStateResult {
  const [emblaRef, emblaApi] = useEmblaCarousel(emblaOptions);
  const initialIndex = emblaOptions.startIndex ?? 0;

  // External-store subscription for currentIndex — no setState in effect.
  const subscribe = useCallback(
    (callback: () => void) => {
      if (!emblaApi) return () => {};
      emblaApi.on("select", callback);
      emblaApi.on("reInit", callback);
      return () => {
        emblaApi.off("select", callback);
        emblaApi.off("reInit", callback);
      };
    },
    [emblaApi],
  );

  const getSnapshot = useCallback(
    () => emblaApi?.selectedScrollSnap() ?? initialIndex,
    [emblaApi, initialIndex],
  );

  const getServerSnapshot = useCallback(() => initialIndex, [initialIndex]);

  const currentIndex = useSyncExternalStore(
    subscribe,
    getSnapshot,
    getServerSnapshot,
  );

  // Stable ref for onSelect callback — avoids effect cascade on identity change.
  const onSelectRef = useRef(onSelect);
  useEffect(() => {
    onSelectRef.current = onSelect;
  });

  // Fire user `onSelect` only on real slide changes — skip the initial mount. A last-notified
  // index (not a first-run flag) so StrictMode's effect replay stays silent too.
  const lastNotifiedRef = useRef<number | null>(null);
  useEffect(() => {
    if (lastNotifiedRef.current === null) {
      lastNotifiedRef.current = currentIndex;
      return;
    }
    if (lastNotifiedRef.current === currentIndex) return;
    lastNotifiedRef.current = currentIndex;
    onSelectRef.current?.(currentIndex);
  }, [currentIndex]);

  // A React options change re-inits Embla with the caller's options, and `startIndex` in them
  // wins over the slide Embla was on — put it back, without animating and without a callback.
  const lastIndexRef = useRef(initialIndex);
  useEffect(() => {
    lastIndexRef.current = currentIndex;
  }, [currentIndex]);
  useEffect(() => {
    if (!emblaApi) return;
    const restore = () => {
      const last = lastIndexRef.current;
      if (emblaApi.selectedScrollSnap() !== last) emblaApi.scrollTo(last, true);
    };
    emblaApi.on("reInit", restore);
    return () => {
      emblaApi.off("reInit", restore);
    };
  }, [emblaApi]);

  const scrollTo = useCallback(
    (index: number) => {
      emblaApi?.scrollTo(index);
    },
    [emblaApi],
  );
  const scrollPrev = useCallback(() => {
    emblaApi?.scrollPrev();
  }, [emblaApi]);
  const scrollNext = useCallback(() => {
    emblaApi?.scrollNext();
  }, [emblaApi]);

  return {
    ref: emblaRef,
    api: emblaApi ?? null,
    currentIndex,
    scrollTo,
    scrollPrev,
    scrollNext,
  };
}

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

"use client";

import { useEffect, useState, useSyncExternalStore } from "react";

const FINE_POINTER = "(pointer: fine)";

function subscribeFinePointer(onChange: () => void) {
  if (typeof window === "undefined" || !window.matchMedia) return () => {};
  const mq = window.matchMedia(FINE_POINTER);
  mq.addEventListener("change", onChange);
  return () => mq.removeEventListener("change", onChange);
}

const readFinePointer = () =>
  typeof window !== "undefined" && !!window.matchMedia && window.matchMedia(FINE_POINTER).matches;
const serverFalse = () => false;
const STEPS = Array.from({ length: 21 }, (_, i) => i / 20);

/**
 * True under a fine pointer (mouse / trackpad). The server snapshot is `false`, so the server
 * render and the hydrating client render agree; the real value lands right after hydration.
 */
export function useFinePointer(): boolean {
  return useSyncExternalStore(subscribeFinePointer, readFinePointer, serverFalse);
}

/**
 * True while at least `threshold` of the element is in the viewport — or, for an element
 * taller than the viewport, while it covers at least `threshold` of the viewport. Starts `true`
 * (server, first render, and environments without IntersectionObserver), so nothing that
 * depends on it changes before mount.
 */
export function useInView(
  ref: React.RefObject<HTMLElement | null>,
  threshold = 0.5,
): boolean {
  const [inView, setInView] = useState(true);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[entries.length - 1];
        if (!entry) return;
        // A carousel taller than the viewport can never be half visible: then covering at
        // least `threshold` of the viewport counts as in view.
        const viewport = entry.rootBounds?.height ?? 0;
        const coversViewport =
          viewport > 0 && (entry.intersectionRect?.height ?? 0) >= viewport * threshold;
        setInView(
          entry.isIntersecting && (entry.intersectionRatio >= threshold || coversViewport),
        );
      },
      // Fine steps: the tall-element rule depends on the visible height, not one ratio crossing.
      { threshold: STEPS },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref, threshold]);
  return inView;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { MediaItem } from "../types";

type Recovery = (item: MediaItem) => Promise<string | void> | string | void;

/** One entry per item id + host URL: the host changing `url` starts over. */
const basisOf = (item: MediaItem) => `${item.id}\u0000${item.url}`;

export interface MediaRecovery {
  /** The URL to render: the replacement after a successful recovery, else `item.url`. */
  urlFor: (item: MediaItem) => string;
  /** Call from the media element's `error` event. */
  onError: (item: MediaItem) => void;
  /**
   * Same as `onError`, as a promise of the replacement URL (void when there is none, or when this
   * item + URL was already asked). For `VideoPlayer`'s `onMediaError`, so the player shows its
   * buffering state while the refresh runs and resumes at the same time afterwards.
   */
  request: (item: MediaItem) => Promise<string | void>;
  /** A host `onMediaError` exists. */
  enabled: boolean;
}

/**
 * `onMediaError` once per item + URL (C8): a resolved string replaces the URL and the element
 * retries; a second failure (of the replacement, or after a void / rejected answer) never asks
 * again. Without a handler it does nothing.
 */
export function useMediaRecovery(onMediaError: Recovery | undefined): MediaRecovery {
  const [replacements, setReplacements] = useState<Record<string, string>>({});
  const askedRef = useRef(new Set<string>());
  const handlerRef = useRef(onMediaError);
  useEffect(() => {
    handlerRef.current = onMediaError;
  });

  const urlFor = useCallback(
    (item: MediaItem) => replacements[basisOf(item)] ?? item.url,
    [replacements],
  );

  const request = useCallback(
    (item: MediaItem) =>
      new Promise<string | void>((resolve) => {
        const handler = handlerRef.current;
        const basis = basisOf(item);
        if (!handler || askedRef.current.has(basis)) {
          resolve();
          return;
        }
        askedRef.current.add(basis);
        const apply = (next: string | void) => {
          if (typeof next === "string" && next && next !== item.url) {
            setReplacements((prev) => ({ ...prev, [basis]: next }));
            resolve(next);
          } else {
            resolve();
          }
        };
        try {
          const result = handler(item);
          if (result && typeof (result as Promise<unknown>).then === "function") {
            (result as Promise<string | void>).then(apply, () => resolve());
          } else {
            apply(result as string | void);
          }
        } catch {
          // A throwing handler is a failed recovery: keep the broken media, never ask again.
          resolve();
        }
      }),
    [],
  );

  const onError = useCallback(
    (item: MediaItem) => {
      void request(item);
    },
    [request],
  );

  return { urlFor, onError, request, enabled: onMediaError !== undefined };
}

import type { CSSProperties } from "react";
import type { LinearAspect, MediaCarouselAspect, MediaItem } from "../types";

export const DEFAULT_MIN_RATIO = 4 / 5;
export const DEFAULT_MAX_RATIO = 1.91;

const FIXED_CLASS: Record<LinearAspect, string> = {
  square: "aspect-square",
  video: "aspect-video",
  portrait: "aspect-[3/4]",
  auto: "",
};

/** `w / h` clamped to `[min, max]`; `null` when the size is unknown or invalid. */
export function clampRatio(
  width: number | undefined,
  height: number | undefined,
  min: number,
  max: number,
): number | null {
  if (!width || !height || !Number.isFinite(width / height) || width <= 0 || height <= 0) return null;
  const lo = Math.min(min, max);
  const hi = Math.max(min, max);
  return Math.min(hi, Math.max(lo, width / height));
}

/** The intrinsic size an item declares, if any. */
export function declaredRatio(item: MediaItem | undefined, min: number, max: number): number | null {
  return item ? clampRatio(item.width, item.height, min, max) : null;
}

export interface FrameStyle {
  className: string;
  style?: CSSProperties;
}

const warnedAspects = new Set<string>();
const warnedPeek = new Set<string>();

export const DEFAULT_PEEK_RATIO = 0.075;
export const MAX_PEEK_RATIO = 0.45;

/**
 * `peekRatio` sets the slide width (`1 - 2 x peek`): clamp to `[0, 0.45]`, non-finite -> the
 * default; one dev warning per out-of-range value.
 */
export function resolvePeekRatio(value: number): number {
  if (Number.isFinite(value) && value >= 0 && value <= MAX_PEEK_RATIO) return value;
  if (process.env.NODE_ENV !== "production" && !warnedPeek.has(String(value))) {
    warnedPeek.add(String(value));
    console.warn(`[MediaCarousel] peekRatio ${String(value)} is outside [0, ${MAX_PEEK_RATIO}]; it was adjusted.`);
  }
  if (!Number.isFinite(value)) return DEFAULT_PEEK_RATIO;
  return Math.min(MAX_PEEK_RATIO, Math.max(0, value));
}

function parsePositive(part: string): number | null {
  if (part === "" || part !== part.trim()) return null;
  const n = Number(part);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/** `"W:H"` -> width / height (the same rule as media-editor's crop aspect); `null` when invalid. */
export function parseRatio(aspect: string): number | null {
  const parts = aspect.split(":");
  if (parts.length !== 2) return null;
  const w = parsePositive(parts[0]!);
  const h = parsePositive(parts[1]!);
  if (w === null || h === null) return null;
  const ratio = w / h;
  return Number.isFinite(ratio) && ratio > 0 ? ratio : null;
}

/**
 * The slide frame: a fixed aspect class, a `"W:H"` inline `aspect-ratio` (invalid -> square,
 * one dev warning), or for `natural-clamped` an inline `aspect-ratio` (`ratio` = the clamped
 * natural ratio; square until it is known).
 */
export function frameFor(aspect: MediaCarouselAspect, ratio: number | null): FrameStyle {
  if (aspect === "natural-clamped") {
    if (ratio === null) return { className: "aspect-square" };
    return { className: "", style: { aspectRatio: String(ratio) } };
  }
  if (Object.hasOwn(FIXED_CLASS, aspect)) return { className: FIXED_CLASS[aspect as LinearAspect] };
  const parsed = parseRatio(aspect);
  if (parsed === null) {
    if (process.env.NODE_ENV !== "production" && !warnedAspects.has(aspect)) {
      warnedAspects.add(aspect);
      console.warn(`[MediaCarousel] Invalid aspect "${aspect}": expected "W:H" with positive numbers; using "square".`);
    }
    return { className: FIXED_CLASS.square };
  }
  return { className: "", style: { aspectRatio: String(parsed) } };
}

import {
  defaultMediaCarouselLabels,
  type MediaCarouselLabels,
  type ResolvedMediaCarouselLabels,
} from "../types";

/**
 * Merge `labels` over the defaults (an `undefined` value never erases a default, C2) and turn
 * the deprecated 0.2 string forms of `goToSlide` / `slideAriaLabel` into functions.
 */
export function resolveLabels(labels: MediaCarouselLabels | undefined): ResolvedMediaCarouselLabels {
  const out: ResolvedMediaCarouselLabels = { ...defaultMediaCarouselLabels };
  if (!labels) return out;
  if (labels.carouselLabel !== undefined) out.carouselLabel = labels.carouselLabel;
  if (labels.previousSlide !== undefined) out.previousSlide = labels.previousSlide;
  if (labels.nextSlide !== undefined) out.nextSlide = labels.nextSlide;
  if (labels.counter !== undefined) out.counter = labels.counter;
  if (labels.carouselRoleDescription !== undefined) {
    out.carouselRoleDescription = labels.carouselRoleDescription;
  }
  if (labels.slideRoleDescription !== undefined) out.slideRoleDescription = labels.slideRoleDescription;

  if (labels.captionShowMore !== undefined) out.captionShowMore = labels.captionShowMore;
  if (labels.captionShowLess !== undefined) out.captionShowLess = labels.captionShowLess;
  if (labels.video !== undefined) out.video = labels.video;

  const goTo = labels.goToSlide;
  if (typeof goTo === "function") out.goToSlide = goTo;
  else if (typeof goTo === "string") out.goToSlide = (position) => `${goTo} ${position}`;

  const slide = labels.slideAriaLabel;
  if (typeof slide === "function") out.slideAriaLabel = slide;
  else if (typeof slide === "string") {
    out.slideAriaLabel = (position, total) =>
      // template-ok: deprecated 0.2 string form of slideAriaLabel, kept as an alias
      slide.replace("{index}", String(position)).replace("{total}", String(total));
  }
  return out;
}

/**
 * A valid BCP 47 tag for `locale`, else `"en"`. An invalid tag (`"en_US"` from an i18n library)
 * makes `Intl` throw — that must not take down the render.
 */
export function resolveLocale(locale: string | undefined): string {
  if (!locale) return "en";
  try {
    return Intl.getCanonicalLocales(locale)[0] ?? "en";
  } catch {
    return "en";
  }
}
